    "casse les verrouillages des joueurs et NPC qui te visent, retire gel et ralentissement, empêche leur retour pendant 3 s.": "bricht die Erfassung von Spielern und NPCs, die dich anvisieren, entfernt Einfrieren und Verlangsamung, verhindert ihre Rückkehr für 3 s.",
    "Ce tableau lit tes vraies touches : modifie-les dans Paramètres → Commandes (clique une ligne puis appuie la nouvelle touche).": "Diese Tabelle liest deine echten Tasten: ändere sie unter Einstellungen → Steuerung (Zeile anklicken, dann die neue Taste drücken).",
