    "Changer de firme coûte": "Ein Firmenwechsel kostet",
    "Chaque carte de membre montre vaisseau, map, distance, coque, bouclier et sa cible.": "Jede Mitgliedskarte zeigt Schiff, Karte, Entfernung, Hülle, Schild und sein Ziel.",
    "Chaque chargement coûte 100 unités du minerai choisi. Changer de minerai remplace le stock en cours. Le chargement se fait dans la fenêtre Raffinage (onglet Upgrade) ou automatiquement (Soute du BOT).": "Jede Ladung kostet 100 Einheiten des gewählten Erzes. Ein Erzwechsel ersetzt den aktuellen Vorrat. Geladen wird im Raffinerie-Fenster (Tab Upgrade) oder automatisch (Laderaum des BOTS).",
    "Chaque compétence a des prérequis (points investis dans d'autres compétences).": "Jede Fähigkeit hat Voraussetzungen (in andere Fähigkeiten investierte Punkte).",
    "chaque famille existe en 3 forces ; Boss ≈ ×4 et Uber ≈ ×8 les gains du normal.": "jede Familie gibt es in 3 Stärken; Boss ≈ ×4 und Uber ≈ ×8 der normalen Gewinne.",
    "Chaque firme a une base en X-1 et en X-8 : réparation, comptoir, zone sûre.": "Jede Firma hat eine Basis in X-1 und in X-8: Reparatur, Handelsposten, sichere Zone.",
    "Chaque hangar a 2 configurations indépendantes : bascule avec la touche Changer configuration.": "Jeder Hangar hat 2 unabhängige Konfigurationen: wechsle mit der Taste Konfiguration wechseln.",
    "Chaque module a une couleur (rareté), un type et 1 à plusieurs statistiques.": "Jedes Modul hat eine Farbe (Seltenheit), einen Typ und 1 oder mehrere Stats.",
    "Chaque NPC laisse une cargo-box (minerais) réservée au tueur.": "Jeder NPC hinterlässt eine Frachtbox (Erze), die dem Killer vorbehalten ist.",
    "Chaque objectif terminé débloque ses récompenses dans la fenêtre Passe de combat.": "Jedes abgeschlossene Ziel schaltet seine Belohnungen im Battle-Pass-Fenster frei.",
    "Chaque spin peut donner des pièces ; à 100 % des pièces, la gate est construite.": "Jeder Spin kann Teile geben; bei 100 % der Teile ist das Gate gebaut.",
    "Chaque vaisseau acheté crée un hangar ; active-le dans la fenêtre Hangars.": "Jedes gekaufte Schiff erstellt einen Hangar; aktiviere ihn im Hangar-Fenster.",
