    "du plus faible au plus fort sur les maps de firme.": "vom schwächsten zum stärksten auf den Firmenkarten.",
    "Élite": "Elite",
    "En Galaxy Gate, les vies sont limitées et les choix dépendent de la gate.": "In einem Galaxy Gate sind die Leben begrenzt und die Optionen hängen vom Gate ab.",
