    "Entre avec la touche Portail quand le portail de la gate est prêt.": "Betritt es mit der Portal-Taste, wenn das Gate-Portal bereit ist.",
    "Envoie les ressources du Skylab vers la soute du vaisseau.": "Schickt die Skylab-Ressourcen in den Laderaum des Schiffs.",
