    "Être ami ne partage jamais les récompenses.": "Freunde teilen nie Belohnungen.",
    "Évasion I": "Ausweichen I",
    "Évasion II": "Ausweichen II",
    "Exemple : config 1 = full lasers + bouclier, config 2 = full vitesse pour fuir ou voyager.": "Beispiel: Konfig 1 = volle Laser + Schild, Konfig 2 = volle Geschwindigkeit zum Fliehen oder Reisen.",
    "Expérience +100 % et honneur +100 % pendant 2 h.": "Erfahrung +100 % und Ehre +100 % für 2 h.",
    "Expérience du P.E.T +5 % pendant 1 h.": "P.E.T-Erfahrung +5 % für 1 h.",
