    "Prédateur": "Raubtier",
    "Priorité de −100 à 100 : un nombre négatif = cible immédiate (le plus négatif gagne).": "Priorität von −100 bis 100: eine negative Zahl = sofortiges Ziel (die negativste gewinnt).",
    "Prix de vente au comptoir par unité, en crédits.": "Verkaufspreis am Handelsposten pro Einheit, in Credits.",
    "Prix en crédits. Un design reprend les caractéristiques de son vaisseau de base et n'ajoute que ses bonus propres.": "Preis in Credits. Ein Design übernimmt die Eigenschaften seines Basisschiffs und fügt nur seine eigenen Boni hinzu.",
    "Production passive de minerais. Les modules montent de niveau avec crédits, ressources et temps.": "Passive Erzproduktion. Module steigen mit Credits, Ressourcen und Zeit im Level.",
    "Produit du Prometium en continu.": "Produziert ständig Prometium.",
